python3 -c '
import json,re,sys
raw=sys.stdin.read()
try: data=json.loads(raw) if raw.strip() else {}
except Exception: raise SystemExit(0)
cmd=((data.get("tool_input") or data.get("input") or {}).get("command") or data.get("command") or "")
if not cmd: raise SystemExit(0)
if re.search(r"\bgit\s+(commit|push)\b", cmd) and re.search(r"(--no-verify|\s-n\b)", cmd):
    print("Traverse guard: refusing git commit/push with --no-verify. Run the hooks.", file=sys.stderr); raise SystemExit(2)
if re.search(r"\bgit\s+config\b.*core\.hooksPath", cmd):
    print("Traverse guard: refusing to redirect core.hooksPath.", file=sys.stderr); raise SystemExit(2)
for path in ["specs/governance/approved-specs.json",".governance-version","scripts/ci/coverage_gate.sh"]:
    if path in cmd and re.search(r"(>|tee\b|\bmv\s|\bcp\s)", cmd):
        print(f"Traverse guard: refusing shell write targeting {path}.", file=sys.stderr); raise SystemExit(2)
'

